const body = $('Webhook: add-contact-public').first().json.body || {};

// Honeypot — a real visitor never fills this (hidden via CSS on the
// public form); a bot filling every field will. Silently pretend
// success without touching the database.
if ((body.website_hp || '').toString().trim()) {
  return [{ json: { spam: true } }];
}

const LIMITS = { first_name: 150, last_name: 150, job_title: 150, email: 255, secondary_email: 255, phone: 50, secondary_phone: 50, linkedin_url: 255, city: 100, state: 100, zip_code: 20, country: 100, lead_source: 100, timezone: 64 };
// Wrong-typed values (objects/arrays) become '' instead of "[object Object]"; control characters are stripped.
const clean = (v) => (typeof v === 'string' || typeof v === 'number' ? String(v) : '').replace(/[\u0000-\u001f\u007f]/g, ' ').trim();
const EMAIL_RE = /^[^\s@<>"'`,;()\[\]\\]+@[^\s@<>"'`,;()\[\]\\]+\.[^\s@<>"'`,;()\[\]\\]{2,}$/;
function checkLengths(o) {
  for (const [k, max] of Object.entries(LIMITS)) {
    if ((o[k] || '').length > max) throw new Error(`"${k}" is too long (maximum ${max} characters).`);
  }
}

const f = {
  first_name: clean(body.first_name), last_name: clean(body.last_name),
  email: clean(body.email).toLowerCase(), phone: clean(body.phone),
  job_title: clean(body.job_title), lead_source: clean(body.lead_source) || 'Website Form',
};

if (!f.first_name) throw new Error('"first_name" is required.');
if (!f.email && !f.phone) throw new Error('Either "email" or "phone" is required.');
if (f.email && !EMAIL_RE.test(f.email)) throw new Error('"email" is not valid.');
checkLengths(f);

return [{
  json: {
    spam: false, source: 'public',
    first_name: f.first_name, last_name: f.last_name, email: f.email, secondary_email: '', phone: f.phone, secondary_phone: '',
    job_title: f.job_title, account_id: null, linkedin_url: '', city: '', state: '', zip_code: '', country: '',
    lead_status: 'New', lead_source: f.lead_source, timezone: '',
    do_not_contact: false, dnc_email: false, dnc_call: false, dnc_sms: false,
    ownerId: null, createdBy: null,
  },
}];

const requester = $input.first().json;
if (!requester.id || !requester.active) throw new Error('Invalid session.');
const body = $('Webhook: add-contact').first().json.body || {};

const LIMITS = { first_name: 150, last_name: 150, job_title: 150, email: 255, secondary_email: 255, phone: 50, secondary_phone: 50, linkedin_url: 255, city: 100, state: 100, zip_code: 20, country: 100, lead_source: 100, timezone: 64 };
// Wrong-typed values (objects/arrays) become '' instead of "[object Object]"; control characters are stripped.
const clean = (v) => (typeof v === 'string' || typeof v === 'number' ? String(v) : '').replace(/[\u0000-\u001f\u007f]/g, ' ').trim();
const EMAIL_RE = /^[^\s@<>"'`,;()\[\]\\]+@[^\s@<>"'`,;()\[\]\\]+\.[^\s@<>"'`,;()\[\]\\]{2,}$/;
function checkLengths(o) {
  for (const [k, max] of Object.entries(LIMITS)) {
    if ((o[k] || '').length > max) throw new Error(`"${k}" is too long (maximum ${max} characters).`);
  }
}

const STATUSES = ['New', 'Active', 'Customer', 'Inactive', 'Unqualified', 'Do Not Contact'];
const asBool = (v) => v === true || v === 'true';
const isBlank = (v) => v === undefined || v === null || v === '';

const f = {
  first_name: clean(body.first_name), last_name: clean(body.last_name),
  email: clean(body.email).toLowerCase(), secondary_email: clean(body.secondary_email).toLowerCase(),
  phone: clean(body.phone), secondary_phone: clean(body.secondary_phone), job_title: clean(body.job_title),
  linkedin_url: clean(body.linkedin_url), city: clean(body.city), state: clean(body.state),
  zip_code: clean(body.zip_code), country: clean(body.country), lead_source: clean(body.lead_source), timezone: clean(body.timezone),
};
if (!f.first_name) throw new Error('"first_name" is required.');
if (f.email && !EMAIL_RE.test(f.email)) throw new Error('"email" is not valid.');
if (f.secondary_email && !EMAIL_RE.test(f.secondary_email)) throw new Error('"secondary_email" is not valid.');
checkLengths(f);

const leadStatus = clean(body.lead_status) || 'New';
if (!STATUSES.includes(leadStatus)) throw new Error(`"lead_status" must be one of ${STATUSES.join(', ')}.`);

let accountId = null;
if (!isBlank(body.account_id)) {
  accountId = Number(body.account_id);
  if (!Number.isInteger(accountId) || accountId <= 0) throw new Error('"account_id" must be a valid company id.');
}
// Only an admin may hand a brand-new contact to someone else at creation time.
let ownerId = requester.id;
if (requester.role === 'admin' && !isBlank(body.owner_id)) {
  ownerId = Number(body.owner_id);
  if (!Number.isInteger(ownerId) || ownerId <= 0) throw new Error('"owner_id" must be a valid user id.');
}

return [{
  json: {
    spam: false, source: 'manual', requesterId: requester.id,
    ...f, account_id: accountId, lead_status: leadStatus,
    do_not_contact: asBool(body.do_not_contact), dnc_email: asBool(body.dnc_email),
    dnc_call: asBool(body.dnc_call), dnc_sms: asBool(body.dnc_sms),
    ownerId, createdBy: requester.id,
  },
}];

// A resubmission / repeat manual-add of the same email updates the
// existing lead instead of creating a duplicate or rejecting outright —
// consistent dedup-by-email across both entry points now.
const payload = $('Normalize Payload').item.json;
const existing = $input.first().json;
return [{ json: { ...payload, existingContactId: existing?.id || null } }];

function tc(s) { return (s || '').toString().toLowerCase().split(' ').map((w) => (w ? w[0].toUpperCase() + w.slice(1) : w)).join(' '); }
function safeEnv(key) { try { return $env[key] || ''; } catch (e) { return ''; } }
// Contact-supplied values are untrusted (the public form is open to anyone). The body is HTML, so they are
// HTML-escaped there; in the subject they are plain text with line breaks removed (no header injection).
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const plain = (s) => String(s ?? '').replace(/[\r\n]+/g, ' ');
const tmpl = $input.item.json;
const row = $('Postgres: Upsert Contact').item.json;
const p = $('Normalize Payload').item.json;
// Same merge tokens the template editor offers (see src/utils/emailTemplateTokens.ts).
const map = {
  'contact.first_name': tc(row.first_name) || 'there',
  'contact.last_name': tc(p.last_name),
  'contact.full_name': tc(`${row.first_name || ''} ${p.last_name || ''}`.trim()),
  'contact.email': row.email || '',
  'contact.phone': p.phone || '',
  // Company names are used exactly as stored (title-casing would turn "GD" into "Gd" and "HOA" into "Hoa").
  'company.name': (tmpl.contact_company_name || '').toString() || 'your company',
  'user.company_name': (tmpl.our_company_name || '').toString(),
};
function fill(t, enc) {
  return (t || '').replace(/{{\s*([\w.]+)\s*}}/g, (m, k) => (Object.prototype.hasOwnProperty.call(map, k) ? enc(map[k]) : ''));
}
const unsubUrl = safeEnv('FRONTEND_BASE_URL') + '/unsubscribe/' + encodeURIComponent(row.unsubscribe_token || '');
const footer = `<br><br><span style="font-size:11px;color:#94a3b8">Don't want these emails? <a href="${unsubUrl}">Unsubscribe</a></span>`;
return [{ json: { to: row.email, subject: fill(tmpl.subject, plain), htmlBody: fill(tmpl.body, esc).replace(/\n/g, '<br>') + footer } }];

